package com.bank.iac;

import java.util.Set;

// Mirrors a Terraform lifecycle{} block.
public class LifecyclePolicy {
    private final boolean preventDestroy;
    private final boolean createBeforeDestroy;
    private final Set<String> ignoredTags;

    public LifecyclePolicy(boolean preventDestroy, boolean createBeforeDestroy,
                           Set<String> ignoredTags) {
        this.preventDestroy = preventDestroy;
        this.createBeforeDestroy = createBeforeDestroy;
        this.ignoredTags = ignoredTags;
    }

    public boolean isPreventDestroy() { return preventDestroy; }
    public boolean isCreateBeforeDestroy() { return createBeforeDestroy; }
    public boolean ignores(String tag) { return ignoredTags.contains(tag); }
}
