package com.bank.iac;

// One resource in the plan: its action, whether the changed attr is immutable,
// which tag (if any) triggered the diff, and its lifecycle policy.
public class PlannedResource {
    private final String address;
    private final ChangeAction action;      // reuse enum CREATE/UPDATE/DESTROY/REPLACE
    private final boolean immutableAttrChanged;
    private final String triggeringTag;      // null if not a tag-only change
    private final LifecyclePolicy policy;

    public PlannedResource(String address, ChangeAction action, boolean immutableAttrChanged,
                           String triggeringTag, LifecyclePolicy policy) {
        this.address = address;
        this.action = action;
        this.immutableAttrChanged = immutableAttrChanged;
        this.triggeringTag = triggeringTag;
        this.policy = policy;
    }

    public String getAddress() { return address; }
    public ChangeAction getAction() { return action; }
    public boolean isImmutableAttrChanged() { return immutableAttrChanged; }
    public String getTriggeringTag() { return triggeringTag; }
    public LifecyclePolicy getPolicy() { return policy; }
}
