package com.bank.iac;

import java.util.logging.Logger;

// Decides whether a planned change is allowed, blocked, must be sequenced, or is a no-op.
public class ChangeGuard {
    private static final Logger log = Logger.getLogger(ChangeGuard.class.getName());

    public enum Decision { ALLOW, BLOCK, SEQUENCE_CBD, SUPPRESS }

    public Decision evaluate(PlannedResource r) {
        LifecyclePolicy p = r.getPolicy();

        // 1) A tag-only diff on an ignored tag should never cause a change.
        if (r.getTriggeringTag() != null && p.ignores(r.getTriggeringTag())) {
            log.info(() -> "SUPPRESS: " + r.getAddress() + " diff on ignored tag '"
                    + r.getTriggeringTag() + "' — no change proposed");
            return Decision.SUPPRESS;
        }

        // 2) A destroy/replace blocked by prevent_destroy must fail loudly.
        if ((r.getAction() == ChangeAction.DESTROY || r.getAction() == ChangeAction.REPLACE)
                && p.isPreventDestroy()) {
            log.severe(() -> "BLOCK: " + r.getAddress() + " would be "
                    + r.getAction() + " but prevent_destroy=true — refusing. "
                    + "Use 'terraform state mv' to rename without recreating.");
            return Decision.BLOCK;
        }

        // 3) A forced replacement from an immutable attribute, but CBD set -> safe sequence.
        if (r.getAction() == ChangeAction.REPLACE && r.isImmutableAttrChanged()) {
            if (p.isCreateBeforeDestroy()) {
                log.warning(() -> "SEQUENCE: " + r.getAddress()
                        + " immutable attr forces replace — create_before_destroy builds "
                        + "new BEFORE destroying old (no downtime)");
                return Decision.SEQUENCE_CBD;
            } else {
                log.severe(() -> "BLOCK: " + r.getAddress()
                        + " immutable replace with NO create_before_destroy — downtime risk!");
                return Decision.BLOCK;
            }
        }

        // 4) Plain create/update in place.
        log.info(() -> "ALLOW: " + r.getAddress() + " " + r.getAction() + " (safe)");
        return Decision.ALLOW;
    }
}
