package com.bank.iac;

import java.util.List;
import java.util.Set;
import java.util.logging.*;

// Runnable demo: three risky changes, each caught by a different guardrail.
public class RecreationGuardDemo {
    private static final Logger log = Logger.getLogger(RecreationGuardDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — evaluating plan against recreation guardrails");

        ChangeGuard guard = new ChangeGuard();

        // EC2 payments instance: AZ change (immutable) but create_before_destroy is on.
        LifecyclePolicy ec2Policy = new LifecyclePolicy(false, true, Set.of());
        PlannedResource ec2 = new PlannedResource("aws_instance.payments",
            ChangeAction.REPLACE, true, null, ec2Policy);

        // S3 statements bucket: rename would destroy it, but prevent_destroy is on.
        LifecyclePolicy s3Policy = new LifecyclePolicy(true, false, Set.of("LastBackup"));
        PlannedResource s3Destroy = new PlannedResource("aws_s3_bucket.statements",
            ChangeAction.DESTROY, false, null, s3Policy);

        // S3 statements bucket: spurious tag diff on an ignored tag.
        PlannedResource s3Tag = new PlannedResource("aws_s3_bucket.statements",
            ChangeAction.UPDATE, false, "LastBackup", s3Policy);

        for (PlannedResource r : List.of(ec2, s3Destroy, s3Tag)) {
            guard.evaluate(r);
        }

        log.info("Guardrails applied: no unexpected recreation reached production.");
    }
}
